import{_ as e,c as o,o as d,a0 as r}from"./chunks/framework.C1J0Vcxi.js";const u=JSON.parse('{"title":"一次 AMP IPC 挂死的三层排查：缓存属性、中断原子性与协议标志位","description":"","frontmatter":{"title":"一次 AMP IPC 挂死的三层排查：缓存属性、中断原子性与协议标志位","date":"2026-08-16","author":"Oveln"},"headers":[],"relativePath":"技术报告/2026-08-16-AMP-IPC挂死三层排查.md","filePath":"技术报告/2026-08-16-AMP-IPC挂死三层排查.md"}'),a={name:"技术报告/2026-08-16-AMP-IPC挂死三层排查.md"};function c(i,t,s,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="一次-amp-ipc-挂死的三层排查-缓存属性、中断原子性与协议标志位" tabindex="-1">一次 AMP IPC 挂死的三层排查：缓存属性、中断原子性与协议标志位 <a class="header-anchor" href="#一次-amp-ipc-挂死的三层排查-缓存属性、中断原子性与协议标志位" aria-label="Permalink to &quot;一次 AMP IPC 挂死的三层排查：缓存属性、中断原子性与协议标志位&quot;">​</a></h1><h2 id="_0-背景" tabindex="-1">0. 背景 <a class="header-anchor" href="#_0-背景" aria-label="Permalink to &quot;0. 背景&quot;">​</a></h2><p>rt-async-amp 的 K3 真板联调收尾阶段，AP（X100 大核，StarryOS，S-mode）与 RP（RT24 rcpu1，rt-async，M-mode）经 RCPU SRAM 共享窗（<code>0xc0800000</code>， 0x19000）上的 ov-channels <code>SharedMemory&lt;3&gt;</code> 通信：ch0 = AP→RP 请求，ch1 = RP→AP 回包；通知面用 mailbox4 硬件门铃代替轮询——AP 侧经 APLIC（MSI 模式， source 217）→ IMSIC 投递，RP 侧是 PLIC IRQ 69。AP 用户态经 <code>/dev/rt_shm</code> 的 ioctl <code>NOTIFY</code>（发完消息打门铃）/<code>AWAIT</code>（停靠等回包门铃）收发。</p><p>验收程序 <code>user-test-ipc</code> 每轮做两件事：发一条 notification 等 RP 回显，再发 一条 ADD RPC 请求等响应，共三轮。</p><p>症状出现在最后一步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./user-test-ipc                                        # 裸跑：卡死在 round-1 的 ADD AWAIT</span></span>
<span class="line"><span>wget 192.168.0.121:8000/user-test-ipc -O ... &amp;&amp; ./user-test-ipc   # 每次都三轮全过</span></span></code></pre></div><p>notification 回显永远正常，挂的只有 ADD。更迷惑的是：先起一个 shell 忙等 任务再裸跑，照样挂——排除了&quot;CPU 休眠/WFI 拖慢唤醒&quot;的假说。</p><p>最终定案：这不是一个 bug，是<strong>叠在一起的三层 bug</strong>，每层都真实存在、都能 独立造成&quot;AWAIT 挂死&quot;这个同一症状。本文按剥洋葱的顺序复盘。</p><hr><h2 id="_1-第一层-x100-上-pbmt-根本不生效-缓存属性" tabindex="-1">1. 第一层：X100 上 PBMT 根本不生效（缓存属性） <a class="header-anchor" href="#_1-第一层-x100-上-pbmt-根本不生效-缓存属性" aria-label="Permalink to &quot;1. 第一层：X100 上 PBMT 根本不生效（缓存属性）&quot;">​</a></h2><p><strong>错误假设</strong>：AP 侧把共享窗 mmap 成 <code>PTE PBMT=NC</code>（Svpbmt 扩展），以为用户态 读写直达 SRAM，天然跨核一致。</p><p><strong>板上实锤</strong>：一切&quot;NC 映射&quot;实际都在走 dcache。X100 的 PMA 按地址判定—— mailbox 等真 MMIO 天然非缓存（所以中断路径一直&quot;正常&quot;），而共享 SRAM 是真 RAM，PMA=cacheable，PTE 写 PBMT=NC 压不住（疑似 OpenSBI 未置 <code>menvcfg.PBMTE</code>，被静默忽略且不报错）。</p><p><strong>修复</strong>：不再信任任何&quot;NC 映射&quot;语义，一致性全部改为显式 CBO（zicbom <code>dcache_range</code>），在 rt_shm 驱动里布了四个同步点：</p><table tabindex="0"><thead><tr><th>时机</th><th>操作</th><th>目的</th></tr></thead><tbody><tr><td>设备初始化</td><td>invalidate</td><td>丢弃启动链（SPL/U-Boot cacheable 写）遗留脏行</td></tr><tr><td>mmap</td><td>invalidate</td><td>清内核早期访问驻留行，用户态首写直达 SRAM</td></tr><tr><td>NOTIFY（门铃前）</td><td>clean+invalidate</td><td>把本核滞留写推到 SRAM 再通知对端</td></tr><tr><td>AWAIT（每次就绪检查前 + 返回前）</td><td>invalidate / clean+invalidate</td><td>读到对端已写入 SRAM 的真值</td></tr></tbody></table><p>其中 AWAIT 有个隐蔽细节：poll 闭包<strong>首查与注册 waker 之间的锁内重查，必须 各自先 invalidate 一次</strong>——首查会把&quot;空&quot;快照取入缓存行，若对端回包恰落在 首查与注册之间，锁内重查会命中首查的陈旧行而误判&quot;无数据&quot;，随后注册、 永久挂死。首查与重查之间只隔几条指令，但这段窗口真实存在。</p><p>这一层修复后，早期的 60/120/180s ping 挂死消失了——但 ADD 裸跑挂死依旧， 且挂点还会随打印多少漂移。说明下面还有。</p><hr><h2 id="_2-第二层-stopei-读写分离吞-msi-中断原子性" tabindex="-1">2. 第二层：stopei 读写分离吞 MSI（中断原子性） <a class="header-anchor" href="#_2-第二层-stopei-读写分离吞-msi-中断原子性" aria-label="Permalink to &quot;2. 第二层：stopei 读写分离吞 MSI（中断原子性）&quot;">​</a></h2><p>AP 的门铃走 IMSIC（MSI 中断控制器）。RISC-V AIA 的 <code>stopei</code> 寄存器语义：</p><ul><li><strong>读</strong>：返回当前最高优先级 pending 中断的（eiid, priority），<strong>非破坏</strong>；</li><li><strong>写</strong>（任意值）：complete 写入时刻的最高优先级 pending，将其清掉。</li></ul><p>原实现把 claim 和 complete 拆成两条指令：进入 handler 前读 <code>stopei</code>，handler 返回时（Drop）再写一次。两条指令之间若有新 MSI 落到更高优先级位，<strong>写的清 掉的是&quot;写入时刻&quot;的新中断而不是刚才处理那个</strong>——新门铃被吞。APLIC 的电平 源（mailbox NEW_MSG）只在 setip 0→1 跳变投一次 MSI，吞一次 = 中断线永久挂 高，后续门铃全部隐形。</p><p>这段弯路的起点是我<strong>记错了语义</strong>——以为&quot;读即 deactivate&quot;，于是做了一个 &quot;QEMU 上跳过补写&quot;的门控 feature。上板把门控关掉，系统直接死在 eth0 DHCP 的第一个外部 MSI 上，门控假说当场证伪。回头查权威实现，三处一致：</p><ul><li>Linux（<code>drivers/irqchip/irq-riscv-imsic-early.c</code>，<code>imsic_handle_irq</code>）： <code>csr_swap(CSR_TOPEI, 0)</code>——单条 <code>csrrw</code>，读写原子，<strong>写在 handler 之前</strong>；</li><li>QEMU（<code>hw/intc/riscv_imsic.c</code>，<code>riscv_imsic_topei_rmw</code>）：“Writes ignore value and clear top pending interrupt&quot;；</li><li>规范原文同上。</li></ul><p>修复：claim 与 complete 合并为单条 <code>csrrw stopei, x0</code>，且前移到 handler 之前（tgoskits <code>feat/riscv-aia</code>，两个 commit）。门控 feature 整体删除。</p><p>这一层是独立的真 bug（不修它，任何 MSI 都可能随机丢）——但修完后 ADD 裸跑 挂死<strong>依旧</strong>。irq 计数证明门铃一枚不少地到达了 AP——那么问题只剩一种可能： <strong>门铃根本没发</strong>。</p><hr><h2 id="_3-第三层-notify-flag-缺失——quiet-回包没有门铃-真凶" tabindex="-1">3. 第三层：NOTIFY_FLAG 缺失——Quiet 回包没有门铃（真凶） <a class="header-anchor" href="#_3-第三层-notify-flag-缺失——quiet-回包没有门铃-真凶" aria-label="Permalink to &quot;3. 第三层：NOTIFY_FLAG 缺失——Quiet 回包没有门铃（真凶）&quot;">​</a></h2><p>决定性证据是一对日志：</p><ul><li>RP 侧：<code>ADD(0,3) 处理完成 … total 1</code>——请求收到、处理了、回包写进 ch1；</li><li>AP 侧：mailbox IRQ 计数停在 2——本轮门铃没来。</li></ul><p>数据到了、中断没到、而中断只有 RP 会发 → 查协议。ov-rpc 约定 <code>method_id</code> 的 <strong>bit63 = NOTIFY_FLAG</strong>：</p><ul><li>带标志：服务端回包后走 <code>HandledKind::Notify</code> → <code>on_notify()</code> → 发 IPI 门铃；</li><li>不带标志：<code>HandledKind::Quiet</code> → 回包进 ch1，<strong>不发任何通知</strong>。</li></ul><p><code>user-test-ipc</code> 手写 <code>Message::request(rid, 1, &amp;(a, b))</code>——method_id 是裸的 <code>1</code>，没带标志。而 ov-rpc 自带的 <code>RpcClient::call()</code> 会自动置位，所以 RP 侧 自己的回显测试一直正常；notification 回显走的又是另一条无条件发门铃的路径 （<code>on_other</code> → <code>send_message()</code>），所以那半边也一直正常。三条&quot;正常&quot;的路把 唯一一条错的路围在中间，掩护到最后。</p><p>修复一行：<code>let method = 1u64 | ov_rpc::NOTIFY_FLAG;</code>。冷启动裸跑多次，三轮 全过。</p><h3 id="wget-为什么能治愈" tabindex="-1">wget 为什么能治愈 <a class="header-anchor" href="#wget-为什么能治愈" aria-label="Permalink to &quot;wget 为什么能治愈&quot;">​</a></h3><p>无门铃时，AWAIT 能否通过是一场 <strong>µs 级赛跑</strong>：</p><ul><li>AP 侧：NOTIFY 返回 → 进入 AWAIT → invalidate → 首次就绪检查，<strong>几十 µs</strong>；</li><li>RP 侧：门铃 → ISR → 唤醒 → 处理 → 回包落 SRAM，<strong>上百 µs</strong>。</li></ul><p>回包赶在首查前落好 → AWAIT 首查即命中，直接返回（我叫它 poll1-luck）； 赶不上 → AWAIT 注册 waker 永久停靠（不会再有任何门铃）。裸跑时 AP 稳赢 前半程——挂。</p><p>wget 跑完后系统里残留着 <strong>ms 级</strong>扰动：eth0 的残余中断流、371KB 新文件的 UFS 写回与块设备完成中断、exec 的脏页缺页等待。这些把 AP 从 NOTIFY 到首查 的路径拖慢一两个数量级，RP 回包总是先到——三轮全过。忙等实验为什么无效？ 它只分走 CPU，不产生中断和 IO，翻不了十倍的数量级差距。</p><p>同一个机制，两个方向的掩蔽：<strong>环境扰动决定竞态胜负时，&quot;通过&quot;是不可信的</strong>。</p><hr><h2 id="_4-参考索引" tabindex="-1">4. 参考索引 <a class="header-anchor" href="#_4-参考索引" aria-label="Permalink to &quot;4. 参考索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考源</th><th>位置</th><th>关键点</th></tr></thead><tbody><tr><td>Linux AIA early handler</td><td><code>drivers/irqchip/irq-riscv-imsic-early.c</code> <code>imsic_handle_irq</code></td><td><code>csr_swap(CSR_TOPEI, 0)</code> 单条 csrrw，写前移</td></tr><tr><td>QEMU IMSIC</td><td><code>hw/intc/riscv_imsic.c</code> <code>riscv_imsic_topei_rmw</code></td><td>写忽略值、清 top pending</td></tr><tr><td>K3 SDK Linux 6.18</td><td><code>~/projects/k3-buildroot-sdk-1.0/bsp-src/linux-6.18</code></td><td>上述文件出处</td></tr><tr><td>ov-rpc 协议</td><td>主仓 <code>modules/ov-rpc/src/{lib,server,client}.rs</code></td><td><code>NOTIFY_FLAG = 1&lt;&lt;63</code>；<code>HandledKind::{Quiet,Notify,OneWay}</code></td></tr><tr><td>rt_shm 驱动设计文档</td><td>tgoskits <code>os/StarryOS/kernel/src/pseudofs/dev/rt_shm.rs</code> 模块头</td><td>缓存一致性模型、四个 CBO 同步点</td></tr><tr><td>K3 mailbox M-mode 侧</td><td>主仓 <code>modules/chip-k3-rt24/src/mailbox.rs</code></td><td>NEW_MSG 电平语义、FIFO 排空模式</td></tr></tbody></table><p>相关提交：tgoskits <code>feat/riscv-aia</code>（EOI 前移 + csrrw 合一）、 <code>feat/rt-async-amp</code>（rt_shm CBO 同步点 + ack 排空 + 窗口收回）；主仓 master（共享窗 SRAM 落位 + 启动期防护；user-test-ipc NOTIFY_FLAG 修复）。</p><hr><p><em>文档完成于 2026-08-16。基于 K3 COM260 开发板真板调试，三轮 RPC 全绿收束。</em></p>`,45)])])}const m=e(a,[["render",c]]);export{u as __pageData,m as default};
